const fmt=(v,d=0)=>Number.isFinite(v)?v.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const money=(v,compact=true)=>{if(!Number.isFinite(v))return '—';const a=Math.abs(v),sign=v<0?'−':'';return sign+'R$ '+(compact&&a>=1e6?fmt(a/1e6,1)+' mi':compact&&a>=1e4?fmt(a/1e3,0)+' mil':fmt(a,compact?0:2));};
const pct=(v,d=1)=>Number.isFinite(v)?fmt(v,d)+'%':'—';
const clone=x=>JSON.parse(JSON.stringify(x));
