const pages=[['dashboard','Visão executiva','dashboard'],['inputs','Premissas','sliders'],['portfolio','Carteira de recebíveis','wallet'],['works','Implantação e obras','work'],['cashflow','Fluxo de caixa','chart'],['scenarios','Cenários e sensibilidade','layers'],['report','Relatório executivo','file'],['method','Metodologia','help']];
let library,storageOK=true;
try{library=JSON.parse(localStorage.getItem(STORE));if(!library||!Array.isArray(library.projects)||!library.projects.length)throw Error();library.projects=library.projects.filter(q=>{try{q.params=E.prepare(q.params);return typeof q.id==='string';}catch{return false;}});if(!library.projects.length)throw Error();}catch{library={active:'demo',projects:[{id:'demo',params:clone(E.defaults),updated:new Date().toISOString()}]};}
let current=library.projects.find(q=>q.id===library.active)||library.projects[0],p=clone(current.params),R,error='',tab=pages.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard',range=36,cashRange='works',cashMode='operation',allAmort=false,heatMetric='peak',sensitivityCache=null,pending=null;
function store(){try{library.active=current.id;localStorage.setItem(STORE,JSON.stringify(library));storageOK=true;}catch{storageOK=false;toast('O navegador não permitiu salvar. Exporte o estudo em JSON para preservar os dados.');}}
