calculate(false);
function date(t){const [y,m]=p.start.split('-').map(Number);return new Date(Date.UTC(y,m-1+t,1)).toLocaleDateString('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}).replace('.','');}
