const colors={green:'#497d58',gold:'#bb914a',red:'#b55742',blue:'#648693'};
function chart(rows,series,options={}){
 if(!rows.length)return '<div class="empty">Sem valores para este período.</div>';
 const W=window.innerWidth<720?480:720,H=options.height||270,L=57,RR=16,T=20,B=35,w=W-L-RR,h=H-T-B,maxT=Math.max(1,rows.at(-1).t),vals=rows.flatMap(r=>series.map(s=>Number(r[s.key])||0)),lo=Math.min(0,...vals),hi=Math.max(1,...vals),span=hi-lo,raw=span/4,mag=10**Math.floor(Math.log10(raw)),step=Math.ceil(raw/mag)*mag,ylo=Math.floor(lo/step)*step,yhi=Math.ceil(hi/step)*step;
 const x=t=>L+t/maxT*w,y=v=>T+(yhi-v)/(yhi-ylo)*h;
 let grid='';for(let v=ylo;v<=yhi+step/100;v+=step){grid+='<line class="'+(v===0?'zero':'grid')+'" x1="'+L+'" x2="'+(W-RR)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text x="'+(L-10)+'" y="'+(y(v)+3)+'" text-anchor="end">'+esc(Math.abs(v)>=1e6?fmt(v/1e6,0)+' mi':Math.abs(v)>=1000?fmt(v/1000,0)+' mil':fmt(v,0))+'</text>';}
 for(let i=0;i<=4;i++){const t=Math.round(maxT*i/4);grid+='<text x="'+x(t)+'" y="'+(H-10)+'" text-anchor="middle">M'+t+'</text>';}
 let lines='';for(const [j,s] of series.entries()){const path=rows.map((r,i)=>(i?'L':'M')+x(r.t).toFixed(2)+','+y(r[s.key]||0).toFixed(2)).join(' ');if(j===0&&options.fill!==false)lines+='<path d="'+path+' L'+x(rows.at(-1).t)+','+y(0)+' L'+x(rows[0].t)+','+y(0)+'Z" fill="'+colors[s.color]+'" fill-opacity=".055"/>';lines+='<path d="'+path+'" fill="none" stroke="'+colors[s.color]+'" stroke-width="2.2" stroke-linejoin="round"/>';}
 const marker=options.marker;let mark='';if(marker!==undefined&&marker<=maxT){const xx=x(marker);mark='<line x1="'+xx+'" x2="'+xx+'" y1="'+T+'" y2="'+(H-B)+'" stroke="#98a88f" stroke-dasharray="3 4"/><text x="'+Math.min(xx+5,W-102)+'" y="12">Entrega · M'+marker+'</text>';}
 const hover=rows.map(r=>'<rect x="'+Math.max(L,x(r.t)-w/maxT/2)+'" y="'+T+'" width="'+Math.max(2,w/maxT)+'" height="'+h+'" fill="transparent"><title>M'+r.t+' — '+series.map(s=>s.label+': '+money(r[s.key],false)).join(' | ')+'</title></rect>').join('');
 return '<div class="legend">'+series.map(s=>'<span><i style="background:'+colors[s.color]+'"></i>'+s.label+'</span>').join('')+'</div><svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(options.title||series.map(s=>s.label).join(' versus '))+'"><title>'+esc(options.title||'Valores nominais por mês')+'</title>'+grid+lines+mark+hover+'</svg>';
}
function dashboard(){const t=R.totals,rows=R.rows.filter(r=>range==='all'||r.t<=range),capital=p.equity+t.draw+t.extra;
 const controls='<div class="segmented">'+[36,60,'all'].map(v=>'<button data-action="range" data-value="'+v+'" class="'+(range===v?'active':'')+'">'+(v==='all'?'Ciclo':v+'m')+'</button>').join('')+'</div>';
 const main=section('Carteira × implantação','Disponibilidade líquida acumulada e desembolsos de obra · R$ nominais',chart(rows,[{key:'cumAvailable',label:'Carteira líquida disponível',color:'green'},{key:'cumWork',label:'Obra acumulada',color:'gold'}],{marker:t.workEnd})+'<p class="chart-note">Carteira líquida = recebimentos esperados menos todos os custos não relacionados à obra. Não inclui aportes nem crédito. A linha pode ser negativa.</p>',controls);
 const sources='<div class="mini-label">Capital próprio + crédito efetivamente usado</div><div class="fund-total">'+money(capital)+'</div><div class="stacked">'+[p.equity,t.draw,t.extra].map(v=>'<i style="width:'+(capital>0?v/capital*100:0)+'%"></i>').join('')+'</div><div class="fund-row"><span>Capital próprio inicial</span><b>'+money(p.equity)+'</b></div><div class="fund-row"><span>Crédito sacado no ciclo</span><b>'+money(t.draw)+'</b></div><div class="fund-row"><span>Aportes adicionais necessários</span><b class="'+(t.extra>1?'negative':'positive')+'">'+money(t.extra)+'</b></div><div class="line"></div><div class="fund-row"><span>Juros + tarifa do crédito</span><b>'+money(t.interest+t.fee)+'</b></div><p class="panel-sub">Valores acumulados no ciclo, não saldos simultâneos. Crédito limite: '+money(p.credit)+'.</p>'+alertBox(t.extra>1?{level:'danger',title:'Há capital ainda não coberto',text:'O modelo exige '+money(t.extra)+' além do aporte inicial e do crédito disponível.'}:{level:'info',title:'Capital suficiente neste cenário',text:'As fontes parametrizadas cobrem o fluxo projetado. Isso não equivale à aprovação de crédito.'});
 const milestones=[12,24,36,48].map(m=>{const r=R.rows[Math.min(m,R.rows.length-1)],v=t.work?Math.max(0,r.cumAvailable)/t.work*100:0;return '<div class="milestone"><div class="month">ATÉ O MÊS '+m+'</div><div class="percent">'+(t.work?pct(v):'—')+'</div><div class="track"><i style="width:'+Math.min(100,v)+'%"></i></div><small>'+money(Math.max(0,r.cumAvailable))+' disponíveis<br>de '+money(t.work)+' de obra total</small></div>';}).join('');
 const diagnosis='<div class="diagnosis"><div class="diagnosis-mark">'+ico('chart')+'</div><div><h3>Vender não é o mesmo que financiar a obra.</h3><p>Na entrega, o cenário prevê <b>'+fmt(t.soldAtCompletion)+' de '+fmt(t.qty)+' lotes vendidos</b>, mas a cobertura potencial da obra é de <b>'+pct(t.coverage)+'</b>. A maior exposição ocorre em <b>M'+t.peakMonth+' ('+date(t.peakMonth)+')</b>: '+money(t.peak)+', antes de crédito e aportes.</p><div class="quick-test">'+btn('test','E com 240 parcelas?','arrow','small','data-test="term"')+btn('test','Entrada de 15%','arrow','small','data-test="entry"')+btn('test','Obra +15%','arrow','small','data-test="work"')+'</div><p class="help-chip">Diagnóstico calculado por regras e simulações. Não utiliza IA generativa.</p></div></div>';
 return heading('Viabilidade, antes de tudo.',esc(p.name)+' <span aria-hidden="true">·</span> '+esc(p.city),btn('navigate','Editar premissas','sliders','','data-page="inputs"')+btn('navigate','Relatório','file','primary','data-page="report"'))+'<div class="kpis">'+kpi('VGV a preços de hoje',money(t.vgv),fmt(t.qty)+' lotes · '+fmt(p.lot)+' m² de área média','work')+kpi('Exposição máxima de caixa',money(t.peak),'M'+t.peakMonth+' · antes de financiamento','chart',true)+kpi('Carteira na entrega',pct(t.coverage),'Cobertura potencial da obra total · M'+t.workEnd,'wallet')+kpi('VPL do empreendimento',money(t.vpl),'TMA '+pct(p.tma,0)+' a.a. · ciclo de '+t.horizon+' meses','layers')+'</div><div class="grid-main">'+main+section('Estrutura de capital','A origem do dinheiro também importa.',sources)+'</div>'+section('Em quanto tempo a carteira contribui?','Cobertura potencial do orçamento total, não apenas da obra executada até cada marco.','<div class="milestones">'+milestones+'</div><p class="chart-note">Meta configurada: '+pct(p.target,0)+'. '+(t.targetMonth!==null?'Primeiro atingimento até a entrega: M'+t.targetMonth+'.':'Não atingida até a entrega neste cenário.')+' A meta é uma premissa de gestão, não um padrão comprovado de mercado.</p>')+'<div style="height:20px"></div>'+section('Leitura do cenário','Os números traduzidos em decisões.',diagnosis);
}
